\section{Preliminaries}
\label{sec:prelims}

\subsection{Notation} \label{sec:notation}
For a bit string $x \in \bits^*$, we denote by $|x|$ its length (not its Hamming weight).
When $x$ describes an instance of a computational problem, we will often use $n = |x|$ to denote its size.

A function $\delta:\N \to [0,1]$ is an \emph{inverse polynomial} if there exists a polynomial $p$ such that $\delta(n) \leq 1/p(n)$ for all sufficiently large $n$. A function $\epsilon:\N \to [0,1]$ is \emph{negligible} if for every polynomial $p$, for all sufficiently large $n$ we have $\epsilon(n) \leq 1/p(n)$. Furthermore for convenience we also assume (unless otherwise stated) all polynomials and error functions are \emph{monotonic}, i.e., for polynomials $p$ we assume that $p(n+1) \geq p(n)$ for all $n$ and for error functions $\eps:\N \to [0,1]$ we have $\eps(n+1) \leq \eps(n)$. When we talk about polynomial or negligible functions with multiple arguments (e.g., $\poly(n,r)$ or $\negl(n,r)$), we mean that it is a polynomial or negligible function in the \emph{sum} of the two arguments (i.e., $\poly(n,r) = \poly(n+r)$ and $\negl(n,r) = \negl(n+r)$). 

A \emph{register} $\reg{R}$ is a named finite-dimensional complex Hilbert space. If $\reg{A}, \reg{B}, \reg{C}$ are registers, for example, then the concatenation $\reg{A} \reg{B} \reg{C}$ denotes the tensor product of the associated Hilbert spaces. We abbreviate the tensor product state $\ket{0}^{\ot n}$ as $\ket{0^n}$. For a linear transformation $L$ and register $\reg R$, we write $L_{\reg R}$ to indicate that $L$ acts on $\reg R$, and similarly we write $\rho_{\reg R}$ to indicate that a state $\rho$ is in the register $\reg R$. We write $\Tr(\cdot)$ to denote trace, and $\Tr_{\reg R}(\cdot)$ to denote the partial trace over a register $\reg R$.

We denote the set of linear transformations on $\reg R$ by $\linear(\reg R)$, and linear transformations from $\reg R$ to another register $\reg S$ by $\linear(\reg R, \reg S)$. We denote the set of positive semidefinite operators on a register $\reg{R}$ by $\pos(\reg{R})$. 
The set of density matrices on $\reg R$ is denoted $\states(\reg R)$.
For a pure state $\ket\varphi$, we write $\varphi$ to denote the density matrix $\ketbra{\varphi}{\varphi}$. We denote the identity transformation by $\id$.
For an operator $X \in \linear(R)$, we define $\| X \|_\infty$ to be its operator norm, and $\| X\|_1 = \Tr(|X|)$ to denote its trace norm, where $|X| = \sqrt{X^\dagger X}$.
We write $\td(\rho,\sigma) = \frac{1}{2} \| \rho - \sigma \|_1$ to denote the trace distance between two density matrices $\rho, \sigma$, and $\fidelity(\rho,\sigma) = \| \sqrt{\rho} \sqrt{\sigma} \|_1^2$ for the fidelity between $\rho, \sigma$. Throughout the paper we frequently invoke the following relationship between fidelity and trace distance:

\begin{proposition}[Fuchs-van de Graaf inequalities]
For all density matrices $\rho,\sigma$ acting on the same space, we have that
\[
    1 - \sqrt{\fidelity(\rho,\sigma)} \leq \td(\rho,\sigma) \leq \sqrt{1 - \fidelity(\rho,\sigma)}\,.
\]
\end{proposition}

A \emph{quantum channel} from register $\reg A$ to $\reg B$ is a completely positive and trace-preserving (CPTP) map from $\linear(\reg A)$ to $\linear(\reg B)$.
For simplicity, we often write $\cN: \reg A \to \reg B$ instead of $\cN: \linear(\reg A) \to \linear(\reg B)$ when it is clear that $\cN$ is a channel. 
We denote the set of quantum channels as $\cptp(\reg A, \reg B)$.
We also call a channel a \emph{superoperator}.
For a channel $\Phi$, we write $\supp(\Phi)$ to denote the number of qubits it takes as input. 
We call a channel unitary (resp.~isometric) if it conjugates its input state with a unitary (resp.~isometry).
The diamond norm of a channel $\Phi \in \cptp(\reg A,\reg B)$ is defined as $\| \Phi \|_\diamond = \max_\rho \| (\Phi \otimes \id_{\reg C})(\rho) \|_1$ where the maximization is over all density matrices $\rho \in \states(\reg A \otimes \reg C)$ where $\reg C$ is an arbitrary register.  

\subsection{Partial isometries and channel completions}

\begin{definition}[Partial isometry] \label{def:partial_iso}
A linear map $U \in \linear(\reg A, \reg B)$ is called a partial isometry if there exists a projector $\Pi \in \linear(\reg A)$ and an isometry $\tilde U \in \linear(\reg A, \reg B)$ such that $U = \tilde U \Pi$.
We call the image of the projector $\Pi$ the \emph{support} of the partial isometry $U$.
\end{definition}

\begin{definition}[Channel completion] \label{def:channel_completion}
Let $U \in \linear(\reg A, \reg B)$ be a partial isometry. 
A \emph{channel completion of $U$} is a quantum channel $\Phi \in \cptp(\reg A, \reg B)$ such that for any input state $\rho \in \states(\reg A)$, 
\begin{align*}
    \Phi(\Pi \rho \Pi) = U \rho  U^\dagger\,,
\end{align*}
where $\Pi \in \linear(\reg A)$ is the projector onto the support of $U$.
If $\Phi$ is a unitary or isometric channel, we also call $\Phi$ a \emph{unitary} or \emph{isometric completion} of the partial isometry.

An \emph{$\epsilon$-error channel completion of $U$} is a quantum channel $\tilde{\Phi}$ that is $\epsilon$-close in diamond norm to a channel completion $\Phi$ of $U$. 
\end{definition}

\subsection{Quantum circuits} \label{sec:qcircuits}
For convenience we assume that all quantum circuits use gates from the universal gate set $\{ H, \mathit{CNOT}, T \}$. A \emph{unitary quantum circuit} is one that consists only of gates from this gate set. A \emph{general quantum circuit} is a quantum circuit that can additionally have non-unitary gates that (a) introduce new qubits initialized in the zero state, (b) trace them out, or (c) measure them in the standard basis. We say that a general quantum circuit has size $s$ if the total number of gates is at most $s$. We say that a general quantum circuit uses space $s$ if the number of qubits involved at every time step of the computation is at most $s$. The description of a general quantum circuit is a sequence of gates (unitary or non-unitary) along with a specification of which qubits they act on.
A general quantum circuit $C$ implements a quantum channel; we will abuse notation slightly and also use $C$ to denote the channel.
For a unitary quantum circuit $C$ we will write $\ket{C}$ to denote the state $C \ket{0 \dots 0}$.

\begin{definition}[Polynomial-size and polynomial-space circuit families] \label{def:poly_circuits}
A family of general quantum circuits $(C_{x, r})_{x \in \{0,1\}^*, r \in \N}$ has \emph{polynomial-size} (resp.~\emph{polynomial-space}) if there exists a polynomial $p$ such that $C_{x, r}$ has size (resp.~uses space) at most $p(|x|, r)$. 
\end{definition}

\begin{definition}[Uniform circuit families] \label{def:uniform_ckt}
A family of general polynomial-size (resp.~polynomial-space) quantum circuits $(C_{x, r})_{x \in \bits^*, r \in \N}$ is called \emph{time-uniform} (resp.~\emph{space-uniform}) if there exists a classical polynomial-time (resp.~polynomial-space) Turing machine that on input $(x, 1^r)$ outputs the description of $C_{x,r}$,\footnote{We adopt the convention that the output tape of a Turing machine is write-only, and does not contribute to the space usage of the Turing machine. Thus a polynomial-space Turing machine can output an exponentially-long string.} where $1^r$ means $r$ written in unary. 
For brevity, we use \emph{uniform} to mean \emph{time-uniform}.
We call a time-uniform (resp.~space-uniform) family of quantum circuits a \emph{polynomial-time quantum algorithm} (resp.~\emph{polynomial-space quantum algorithm}).
\end{definition}

\begin{definition}[Unitary purification of a general quantum circuit]
\label{def:unitary-purification}
A \emph{unitary purification} (or \emph{dilation}) of a general quantum circuit $C$ is a unitary circuit $\tilde{C}$ formed by performing all measurements in $C$ coherently (with the help of additional ancillas) and not tracing out any qubits. 
\end{definition}

\subsection{Quantum interactive protocols}
\label{sec:interactive-protocols}

More formally, a \emph{$k$-round quantum verifier circuit} $C = (C_j)_{j \in [k]}$ is a tuple of general quantum circuits that each act on a pair of registers $(\reg{V},\reg{M})$. The circuit $C_j$ should be thought of as the verifier's actions in the $j$-th round of the protocol. The register $\reg{V}$ is further divided into disjoint sub-registers $(\reg{V}_\work, \reg{V}_\flag, \reg{V}_\out)$. The register $\reg V_\work$ is the verifier circuit's ``workspace'', the register $\reg V_\flag$ is a single qubit indicating whether the verifier accepts or rejects, and the register $\reg V_\out$ holds the verifier's output (if applicable). The register $\reg{M}$ is the message register. The size of a verifier circuit $C$ is the sum of the circuit sizes of the $C_j$'s.

A \emph{quantum prover} $P$ for a verifier circuit $C$ is a unitary that acts on $\reg{M}$ as well as a disjoint register $\reg{P}$.

Let $\ket{\psi}$ denote a quantum state whose size is at most the number of qubits in $\reg{V}_\work$. We write $C(\ket{\psi}) \interact P$ to denote the interaction between the verifier circuit $C$ and the prover $P$ on input $\ket{\psi}$, which is defined according to the following process. The initial state of the system is $\ket{\phi_0} = \ket{\psi,\zs}_{\reg V_\work} \ket\zs_{\reg{V}_\flag \reg{V}_\out \reg{M} \reg{P}}$. Inductively define $\ket{\phi_i} = P \ket{\phi_{i-1}}$ for odd $i \leq 2k$, and $\ket{\phi_i} = C_{i/2} \ket{\phi_{i-1}}$ for even $i \leq 2k$. We say that $C(\ket{\psi}) \interact P$ accepts (resp.~rejects) if measuring the register $\reg{V}_\flag$ in the state $\ket{\phi_{2k}}$ in the standard basis yields the outcome $1$ (resp.~$0$). We say that the \emph{output of $C(\ket{\psi}) \interact P$ conditioned on accepting} is the density matrix
\[
\frac{\Tr_{\reg{V} \reg{M} \reg{P} \setminus \reg{V}_\out} \left( \ketbra{1}{1}_{\reg{V}_\flag} \cdot \phi_{2k} \right)}{\Tr \left( \ketbra{1}{1}_{\reg{V}_\flag} \cdot \phi_{2k} \right)}\,;
\]
in other words, it is the reduced density matrix of $\ket{\phi_{2k}}$ on register $\reg{V}_\out$, conditioned on $C(\ket{\psi}) \interact P$ accepting. (If the probability of accepting is $0$, then we leave the output undefined.) 

A \emph{quantum verifier} $V = (V_{x,r})_{x \in \bits^*,r \in \N}$ is a time-uniform sequence of polynomial-size and polynomial-round quantum verifier circuits.

\subsection{Quantum state complexity classes}
\label{sec:prelims-state-complexity}

\begin{definition}[$\stateBQP$, $\statePSPACE$] \label{def:stateclasses}
	The class $\stateBQP$ (resp.~$\statePSPACE$) is the set of all sequences of density matrices $(\rho_x)_{x \in \bits^*}$ such that there exists a time-uniform polynomial-size (resp.~space-uniform polynomial-space) family of general quantum circuits $(C_{x,r})_{x \in \bits^*,r \in \N}$, where $C_{x,r}$ takes no inputs, and for every $x \in \bits^*$ and $r \in \N$, the output $\sigma_{x,r}$ of $C_{x,r}$ satisfies 
	\[
	\td(\sigma_{x,r}, \rho_x) \leq \frac{1}{r}\,.
	\]
\end{definition}

\begin{definition}[{$\stateQIP$}]
	\label{def:stateQIP}
        Let $c,s:\N \times \N \to [0,1]$ be functions. The class $\stateQIP_{c,s}$ is the set of state sequences $(\rho_x)_{x \in \bits^*}$ where there exists a time-uniform polynomial-time quantum verifier $V = (V_{x,r})_{x \in \bits^*,r\in \N}$ such that for all $x \in \bits^*$ and $r \in \N$:
	\begin{itemize}
		\item \emph{Completeness:} There exists a quantum prover $P^*$ (called an \emph{honest prover}) such that
		\begin{equation*}
			\pr {V_{x,r} \interact P^* \text{ accepts}} \geq c(|x|,r)~. \end{equation*}
\item \emph{Soundness:} For all quantum provers $P$, it holds that
		\[
		   \text{if } \quad \pr {V_{x,r} \interact P \text{ accepts}} \geq s(|x|,r) \qquad \text{then} \qquad \td(\sigma, \rho_x) \leq \frac{1}{r}\,,
		\]
		where $\sigma$ denotes the output of $V_{x,r} \interact P$ conditioned on accepting.
	\end{itemize}
	Here the probabilities are over the randomness of the interaction, assuming the verifier starts with the all-zero input state. 

 Finally, define 
    \[
        \stateQIP = \bigcup_{\epsilon(n) \, \negl} \stateQIP_{1-\epsilon,\frac{1}{2}}
    \]
    where the union is over all negligible functions $\epsilon(n,r)$.
\end{definition}

\section{Unitary Synthesis Problems and Unitary Complexity Classes}
\label{sec:defs}

\subsection{Unitary synthesis problems} \label{sec:unitary_synth_problems_def}

\begin{definition}[Unitary synthesis problem] \label{def:unitary_synth_problem}
A \emph{unitary synthesis problem} is a sequence $\mathscr{U} = (U_{x})_{x \in \{0,1\}^*}$ of partial isometries.
\end{definition}

\subsection{Distributional unitary synthesis problems}

\begin{definition}[Distributional unitary synthesis problem]
\label{def:dist-usynth}
We say that a pair $(\usynth{U}, \Psi)$ is a \emph{distributional unitary synthesis problem} if $\usynth{U} = (U_x)_x$ is a unitary synthesis problem with $U_x \in \linear(\reg A_x, \reg B_x)$ for some registers $\reg A_x, \reg B_x$, and $\Psi = (\ket{\psi_x})_x$ is a family of bipartite pure states on registers $\reg A_x \reg R_x$. We call $\ket{\psi_x}$ the \emph{distribution state} with \emph{target register} $\reg{A}_x$ and \emph{ancilla register} $\reg{R}_x$. 
\end{definition}

\begin{definition}[Average-case implementation of distributional unitary synthesis problems] \label{def:avg_case_error}
Let $(\usynth{U},\Psi)$ denote a distributional unitary synthesis problem, where $\usynth{U} = (U_x)_x$ and $\Psi = (\ket{\psi_x})_x$. Let $C = (C_{x, r})_{x \in \bits^{*}, r \in \N}$ denote a family of quantum circuits, where $C_{x, r}$ implements a channel whose input and output registers are the same as those of $U_x$ for all $r \in \N$. We say that \emph{$C$ is an average-case implementation of $(\usynth{U},\Psi)$} if for all $x \in \bits^*$ and $r \in \N$, there exists a channel completion $\Phi_{x,r}$ of $U_x$ such that
\[
\td \Big ( (C_{x, r} \ot \id)(\psi_x), \, (\Phi_{x,r} \ot \id)(\psi_x) \Big ) \leq \frac{1}{r} \,,
\]
where the identity channel acts on the ancilla register of $\ket{\psi_x}$.
\end{definition}

\subsection{Unitary complexity classes}
\label{sec:unitary-complexity-classes}

\begin{definition}[$\avgUnitaryBQP$, $\avgUnitaryPSPACE$]\label{def:avgunitaryBQP_avgunitaryPSPACE}
Define the unitary complexity class $\avgUnitaryBQP$ (resp.~$\avgUnitaryPSPACE$) to be the set of distributional unitary synthesis problems $(\usynth{U},\Psi)$ where $\Psi \in \stateBQP$ (resp.~$\Psi \in \statePSPACE$) and there exists a polynomial-time (resp.~polynomial-space) quantum algorithm $C$ that implements $(\usynth{U},\Psi)$ with average-case error.
\end{definition}

\section{Interactive Proofs for Unitary Synthesis}
\label{sec:protocols}

\subsection{Average-case interactive unitary synthesis}

\begin{definition}[{$\avgUnitaryQIP$}]
	\label{def:avgUnitaryQIP}
        Let $c,s:\N \times \N \to [0,1]$ be functions. The class $\avgUnitaryQIP_{c,s}$ is the set of distributional unitary synthesis problems $(\usynth{U} = (U_x)_x,\Psi = (\ket{\psi_x})_x)$ such that $\Psi \in \stateQIP$ and there exists a polynomial-time quantum verifier $V = (V_{x, r})_{x \in \{0,1\}^*, r \in \N}$ satisfying, for all $x \in \{0,1\}^*$ and $r \in \N$,
	\begin{itemize}
		\item \emph{Completeness:} There exists a quantum prover $P$ (called an \emph{honest prover}) such that 
		\begin{equation*}
			\pr {V_{x, r}(\ket{\psi_x}) \interact P \text{ accepts}} \geq c(|x|, r)
		\end{equation*}
  where $V_{x, r}$ does not have access to the ancilla register of $\ket{\psi_x}$. 
		\item \emph{Soundness:} For all quantum provers $P$, there exists a channel completion $\Phi_{x,r}$ of $U_x$ such that
		\[
		   \text{if } \quad \pr {V_{x, r}(\ket{\psi_x}) \interact P \text{ accepts}} \geq s(|x|, r) \qquad \text{then} \qquad \td(\sigma_{x,r}, (\Phi_{x,r} \ot \id)(\psi_x)) \leq \frac{1}{r} \,,
		\]
		where $\sigma_{x,r}$ denotes the output of $V_{x, r}(\ket{\psi_x}) \interact P$ conditioned on accepting and $V_{x, r}$ does not have access to the ancilla register of $\ket{\psi_x}$. 
	\end{itemize}
	Here the probabilities are over the randomness of the interaction. \end{definition}

\subsection{Zero-knowledge protocols for unitary synthesis}
\label{sec:zk}

\begin{definition}[Honest-verifier, zero-knowledge unitary synthesis] \label{def:avgUnitarySZK}
    Let $c,s,\eps:\N \times \N \to [0,1]$ be functions. The class $\avgUnitary{HVSZK}_{c,s,\eps}$ is the set of distributional unitary synthesis problems $(\usynth{U} = (U_x)_x,\Psi = (\psi_x)_x) \in \avgUnitaryQIP_{c,s}$ such that
    \begin{enumerate}
        \item The distributional state family $\Psi \in \stateBQP$.
        \item There is an \emph{honest verifier} $V^* = (V_{x,r})_{x,r}$ and an \emph{honest prover} $P^*$ satisfying the $\avgUnitaryQIP_{c,s}$ completeness and soundness conditions for $(\usynth{U},\Psi)$, and
        \item There exists a polynomial-time quantum algorithm $\Sim$ (called the \emph{simulator}) ssuch that on input $(x,r,j)$ (for
        $j \in \N$), outputs a state $\rho$ satisfying
        \[
            \td(\rho,\sigma_{x, r,j}) \leq \eps(|x|, r)
        \]
        where $\sigma_{x, r,j}$
        is the joint density matrix of both the honest verifier $V^*_{x, r}$'s private register \emph{and} the ancilla register of the input $\ket{\psi_x}$, immediately after the $j$'th round of interaction with the honest prover $P^*$.
    \end{enumerate}
\end{definition}

\section{The Uhlmann Transformation Problem}
\label{sec:uhlmann}

\subsection{Uhlmann's theorem and canonical Uhlmann transformations} 
\label{sec:uhlmanns_theorem}

\begin{definition}[Canonical Uhlmann transformation]
\label{def:canonical-uhlmann}
The \emph{canonical Uhlmann transformation} corresponding to a pair of pure states $(\ket{C}_{\reg{AB}},\ket{D}_{\reg{AB}})$ is defined as
\begin{equation}
    \label{eq:def-canonical-uhlmann-isometry}
    W = \sgn(\Tr_{\reg{A}}(\ketbra{D}{C}))~.
\end{equation}
\end{definition}

\subsection{Uhlmann Transformation Problem}
\label{subsec:worst_case_uhlmann}

\begin{definition}[Explicit and succinct descriptions of quantum circuits]
An \emph{explicit description} of a unitary quantum circuit $C$ is a sequence $(1^n, g_1,g_2,\ldots)$ where $1^n$ represents in unary the number of qubits that $C$ acts on, and $g_1,g_2,g_3,\ldots$ is a sequence of unitary gates. 

A \emph{succinct description} of a quantum circuit $C$ is a pair $(1^n,\hat{C})$ where $\hat{C}$ is a description of a classical circuit\footnote{Here, we think of $\hat{C}$ as being a list of AND, OR, and NOT gates.}  that takes as input an integer $t$ in binary and outputs the description a unitary gate $g_t$ coming from some universal gate set, as well as the (constant-sized) set of qubits that $g_t$ acts on. Together, the gates $g_1,\ldots,g_T$ describe a circuit $C$ acting on $n$ qubits; we will always denote the classical circuit with a hat (e.g.~$\hat C$) and use the same letter without a hat (e.g.~$C$) for the associated quantum circuit.
\end{definition}

\begin{definition}[Valid Uhlmann instances] \label{def:valid_uhlmann_string}
We say that a string $x \in \bits^*$ is a \emph{valid Uhlmann instance} if it encodes a tuple $(1^n,C,D)$ where $C,D$ are explicit descriptions of \emph{unitary} circuits that each act on $2n$ qubits. We say that $x$ is a \emph{valid succinct Uhlmann instance} if $x = (1^n, \hat C, \hat D)$ is a succinct description of a pair $(C,D)$ of unitary circuits that each act on $2n$ qubits for some $n$. 

We further say that a valid (possibly succinct) Uhlmann instance $x$ is a \emph{fidelity-$\kappa$ instance} if the reduced states $\rho,\sigma$ of the states $\ket{C} = C \ket{0^{2n}}$, $\ket{D} = D \ket{0^{2n}}$ on the first $n$ qubits satisfy $\fidelity(\rho,\sigma) \geq \kappa$.
\end{definition}

\begin{definition}[Uhlmann Transformation Problem] \label{def:utp}
Let $\kappa:\N \to [0,1]$ be a function. The \emph{$\kappa$-fidelity Uhlmann Transformation Problem} is the unitary synthesis problem $\Uhlmann_{\kappa} = (U_x)_{x \in \bits^*}$ where whenever $x = (1^n,C,D)$ is a fidelity-$\kappa(n)$ Uhlmann instance specifying a pair $(C,D)$ of unitary circuits that each act on $2n$ qubits for some $n$, then $U_x$ is the canonical Uhlmann transformation for the pair of states $(\ket{C},\ket{D}$). Otherwise if $x$ is not a valid Uhlmann instance, then we define $U_x = 0$ (i.e., a partial isometry with zero-dimensional support). 

The \emph{$\kappa$-fidelity Succinct Uhlmann Transformation Problem}, denoted by $\SuccinctUhlmann_{\kappa}$, is the sequence $(U_x)_x$ where whenever $x = (1^n,\hat{C},\hat{D})$ is a valid fidelity-$\kappa(n)$ succinct Uhlmann instance specifying a pair $(C,D)$ of unitary circuits that each act on $2n$ qubits for some $n$, then $U_x$ is the canonical Uhlmann transformation for the pair of states $(\ket{C},\ket{D})$; if $x$ is not a valid succinct Uhlmann instance, then we define $U_x = 0$. \end{definition}

\subsection{Distributional Uhlmann Transformation Problem}
\label{subsec:dist_uhlmann}

\begin{definition}[Distributional Uhlmann Transformation Problems] \label{def:canonical_dist_UTP}
We define a state sequence $\Psi_{\Uhlmann} = (\ket{\psi_x})_{x \in \bits^*}$ as follows: for all $x \in \{0,1\}^*,$
\[
    \ket{\psi_x} = \begin{cases}
        \ket{C} & \text{if $x = (1^n,C,D)$ is valid Uhlmann instance,} \\
        0 & \text{otherwise.}
    \end{cases}
\]
Then, the \emph{distributional $\kappa$-fidelity Uhlmann Transformation Problem} is the distributional unitary synthesis problem $\DistUhlmann_{\kappa} = (\Uhlmann_{\kappa}, \Psi_{\Uhlmann})$.

The state sequence $\Psi_{\SuccinctUhlmann}$ and the distributional unitary synthesis problem $\DistSuccinctUhlmann_\kappa$ are defined analogously.

\end{definition}

\section{Quantum Cryptography}
\label{sec:qcrypto}

\subsection{Quantum bit commitments}\label{sec:commitments}

\begin{definition}[Canonical quantum bit commitment~\cite{yan2023general}]\label{def:commitment_scheme}
A \emph{canonical non-interactive quantum bit commitment scheme} is given by a uniform family of unitary quantum circuits $\{ C_{\lambda,b} \}_{\lambda \in \N,b \in \{0,1\}}$ where for each $\lambda$, the circuits $C_{\lambda,0},C_{\lambda,1}$ act on $poly(\lambda)$ qubits and output two registers $\reg{C},\reg{R}$. The scheme has two phases:
\begin{enumerate}
    \item In the \emph{commit stage}, to commit to a bit $b \in \{0,1\}$, the sender prepares the state $\ket{\psi_{\lambda,b}}_{\reg{RC}} = C_{\lambda,b} \ket{0 \cdots 0}$, and then sends the ``commitment register'' $\reg{C}$ to the receiver. 

    \item In the \emph{reveal stage}, the sender announces the bit $b$ and sends the ``reveal register'' $\reg{R}$ to the receiver. The receiver then accepts if performing the inverse unitary $C_{\lambda,b}^\dagger$ on registers $\reg{C},\reg{R}$ and measuring in the computational basis yields the all zeroes state.
\end{enumerate}
\end{definition}

\begin{definition}[Hiding property of commitment scheme]\label{def:hiding_commitment}
    Let $\eps(\lambda)$ denote a function. We say that a commitment scheme $\{ C_{\lambda,b} \}_{\lambda,b}$ satisfies \emph{$\eps$-computational (resp.~$\eps$-statistical) hiding} if for all polynomial-time algorithms  (resp.~for all algorithms) $A = (A_\lambda)_\lambda$ that take as input the commitment register $\reg{C}$ of the scheme $\{ C_{\lambda,b} \}_{\lambda,b}$, the following holds for sufficiently large $\lambda$:
    \begin{equation}\label{eqn:commitment_hiding_property}
        \Big | \Pr \Big [ A_\lambda(\rho_{\lambda,0}) = 1 \Big ]- \Pr \Big [ A_\lambda(\rho_{\lambda,1}) = 1\Big ] \Big | \leq \eps(\lambda) \,.
    \end{equation}
    Here, $\rho_{\lambda,b}$ denotes the reduced density matrix of $\ket{\psi_{\lambda,b}}$ on register $\reg{C}$. 
    If $\eps$ is a negligible function of $\lambda$ then we simply say that the scheme satisfies \emph{strong} computational (resp.~statistical) hiding. 

\end{definition}

\begin{definition}[Honest binding property of commitment scheme]\label{def:honest_binding}
    Let $\eps(\lambda)$ denote a function. We say that a commitment scheme $\{ C_{\lambda,b} \}_{\lambda,b}$ satisfies \emph{$\eps$-computational (resp.~$\eps$-statistical) honest binding} if for all polynomial-time algorithms  (resp.~for all algorithms) $A = (A_\lambda)_\lambda$ that take as input the reveal register $\reg{R}$ the following holds for sufficiently large $\lambda$:
    \begin{equation}
        \fidelity \left( \Big( A_{\lambda} \otimes \id_{\reg{C}} \Big)(\psi_{\lambda,0}) , \psi_{\lambda,1} \right ) \leq \eps(\lambda)\,,
    \end{equation}
    where $\psi_{\lambda,b} = \ketbra{\psi_{\lambda,b}}{\psi_{\lambda,b}}_{\reg{R} \reg{C}}$.

    If $\eps$ is a negligible function of $\lambda$ then we simply say that the scheme satisfies \emph{strong} computational (resp.~statistical) honest binding. \end{definition}

\begin{definition}[Hard unitary synthesis instances]
